"""Single write path for settable memory fields.

Both the batch ``set_fields`` dispatcher
(:meth:`~rasa.mantle.orchestration.skill_executor.SkillExecutor._dispatch_set_fields`)
and the correction executor
(:meth:`~rasa.mantle.orchestration.correction.executor.CorrectionExecutor._apply_correction`)
write a settable memory entry and then run its optional
``run_after_setting_<entry>`` memory validation tool, rolling the write back
when the tool rejects it. That "write, then run the tool, then roll back on
rejection" sequence lives here so the two call sites cannot drift.
"""

from __future__ import annotations

from typing import (
    TYPE_CHECKING,
    Any,
    Awaitable,
    Callable,
    Dict,
    Mapping,
    Optional,
)

from pydantic import BaseModel, ConfigDict

from rasa.mantle.memory.manager import MemoryWriteError
from rasa.mantle.orchestration.memory_validation_tools import (
    extract_tool_error_message,
    memory_validation_tool_name,
    restore_memory_snapshot,
    snapshot_accessible_memory,
    tool_result_indicates_error,
)
from rasa.shared.core.events import create_tool_execution_events

if TYPE_CHECKING:
    from rasa.mantle.state.tracker_handle import TrackerHandle

# Signature of the executor's registered-tool invoker
# (``SkillExecutor.call_tool_func``).
CallToolFunc = Callable[
    [
        Optional[Callable[..., Any]],
        str,
        Dict[str, Any],
        "TrackerHandle",
        Optional[tuple[str, str]],
    ],
    Awaitable[str],
]


class SettableWriteResult(BaseModel):
    """Outcome of writing a settable field and running its memory validation tool.

    ``ok`` is ``True`` on a successful write (and tool, if any). On failure
    ``error`` carries the human-readable reason and ``memory_validation_failed``
    distinguishes a rejecting memory validation tool (write rolled back) from a
    memory write denied by the access contract (nothing written).
    """

    model_config = ConfigDict(frozen=True)

    ok: bool
    error: Optional[str] = None
    memory_validation_failed: bool = False


async def write_settable_field(
    tracker_handle: "TrackerHandle",
    skill_id: str,
    flow_id: str,
    entry_name: str,
    value: Any,
    tool_funcs: Mapping[str, Mapping[str, Callable[..., Any]]],
    call_tool_func: CallToolFunc,
    *,
    button_project_slot_name: str | None = None,
) -> SettableWriteResult:
    """Write *value* to *entry_name*, then run its optional memory validation tool.

    Applies the schema-scoped memory write, then — for top-level writes
    only (never for a write made inside another memory validation tool) —
    invokes the ``run_after_setting_<entry>`` tool registered under *skill_id*
    when one exists. Shared memory validation tools from the agent root are
    merged onto every skill (see
    :func:`~rasa.mantle.tools.loader.load_tools_for_skill_catalog`). A tool
    that returns a JSON error payload rolls the write, and any state the tool
    itself produced, back to the pre-write snapshot.

    Args:
        tracker_handle: Handle for the active turn's tracker/memory.
        skill_id: Skill that owns the entry (``memory.yml`` / write access).
        flow_id: Producing frame's flow id, passed through to
            :meth:`~rasa.mantle.memory.manager.MemoryManager.set`. This may
            differ from a flow of *skill_id* when an ancestor stamped a
            child-owned slot.
        entry_name: Bare settable memory entry name.
        value: Value to write.
        tool_funcs: Skill-scoped tool registry ``{skill_id: {name: func}}``,
            used to look up the memory validation tool.
        call_tool_func: The executor's in-process tool invoker.
        button_project_slot_name: When set by the static ``set:session.project.*``
            button intercept, write this fully-qualified ``project.{entry}`` slot
            instead of resolving *entry_name* through :meth:`MemoryManager.set`.

    Returns:
        A :class:`SettableWriteResult` describing success or the failure reason.
    """
    memory = tracker_handle.memory
    validation_tool_name = memory_validation_tool_name(entry_name)
    validation_tool = tool_funcs.get(skill_id, {}).get(validation_tool_name)
    # These tools run only for top-level writes, never for a write made inside
    # another one (``suppress_memory_validation_tools``).
    run_validation_tool = (
        validation_tool is not None
        and not tracker_handle.memory_validation_tools_suppressed
    )
    snapshot = (
        snapshot_accessible_memory(memory, skill_id, flow_id)
        if run_validation_tool
        else None
    )

    try:
        if button_project_slot_name is not None:
            memory.set_named_project_slot_for_button(button_project_slot_name, value)
        else:
            memory.set(skill_id, flow_id, entry_name, value)
    except MemoryWriteError as exc:
        # Surface the reason so the caller can pass it back to the LLM.
        return SettableWriteResult(ok=False, error=str(exc))

    if validation_tool is None or snapshot is None:
        return SettableWriteResult(ok=True)

    with tracker_handle.suppress_memory_validation_tools():
        validation_tool_result = await call_tool_func(
            validation_tool,
            validation_tool_name,
            {},
            tracker_handle,
            (skill_id, flow_id),
        )

    validation_tool_rejected = tool_result_indicates_error(validation_tool_result)
    # Queue the tool's ToolExecuted so the orchestrator can flush it AFTER
    # the parent tool's own event: set_fields, then the memory validation tool.
    tracker_handle.queue_memory_validation_events(
        create_tool_execution_events(
            tool_name=validation_tool_name,
            arguments={},
            source="local",
            result=validation_tool_result or f"{validation_tool_name}: done",
            is_error=validation_tool_rejected,
            error_message=(
                extract_tool_error_message(validation_tool_result)
                if validation_tool_rejected
                else None
            ),
            skill_id=skill_id or None,
        )
    )

    if validation_tool_rejected:
        restore_memory_snapshot(tracker_handle, snapshot)
        return SettableWriteResult(
            ok=False,
            error=extract_tool_error_message(validation_tool_result),
            memory_validation_failed=True,
        )

    return SettableWriteResult(ok=True)
